def fmt_money(cents):
    sign = "-" if cents < 0 else ""
    dollars, rem = divmod(abs(cents), 100)
    return f"{sign}${dollars:,}.{rem:02d}"

for c in [0, 5, 50, 999, 123456, -250, -7]:
    print(c, "->", fmt_money(c))

def humanize(n):
    if n < 1000:
        return str(n)
    units = ["k", "M", "B"]
    x = n / 1000.0
    i = 0
    while x >= 1000 and i < len(units) - 1:
        x /= 1000
        i += 1
    text = f"{x:.1f}"
    if text == "1000.0" and i < len(units) - 1:
        i += 1
        text = "1.0"
    return text + units[i]

for n in [0, 42, 999, 1000, 1234, 999949, 999999, 3400000, 2500000000]:
    print(n, "->", humanize(n))

