def outline(node, depth=0):
    if isinstance(node, dict):
        for key, child in node.items():
            print("  " * depth + key)
            outline(child, depth + 1)
    else:
        for item in node:
            print("  " * depth + "- " + item)

outline(tree)

def report(title, notes):
    lines = [title, "=" * len(title)]
    lines.append("Status: complete.")
    lines.append("Notes:")
    for n in notes:
        lines.append(f"- {n}")
    return "\n".join(lines)

print(report("Weekly", []))
print("---fixed---")

def report2(title, notes):
    lines = [title, "=" * len(title), "Status: complete."]
    if notes:
        lines.append("Notes:")
        lines.extend(f"- {n}" for n in notes)
    return "\n".join(lines)

print(report2("Weekly", []))
print(report2("Weekly", ["Deploy moved to Friday"]))

def assemble(header, body, footer=None, appendix=None):
    parts = [header, body]
    if footer is not None:
        parts.append(footer)
    if appendix is not None:
        parts.append(appendix)
    return "\n\n".join(parts)

print(assemble("H", "B"))
print("===")
print(assemble("H", "B", footer="F"))

