def money(cents):
    return f"${cents / 100:,.2f}"

def render(order):
    lines = [f"Order {order['id']}"]
    for name, cents in order["items"]:
        lines.append(f"  {name}: {money(cents)}")
    total = sum(c for _, c in order["items"])
    lines.append(f"  total: {money(total)}")
    return "\n".join(lines)

order = {"id": "A-17", "items": [("Notebook", 1250), ("Pen", 199)]}
print(render(order))
